package io.github.qisun8023.filemanager.helper;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.content.res.Configuration;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.webkit.*;import android.graphics.Color;import org.json.*;import java.util.concurrent.*;import java.io.*;
public class MainActivity extends Activity {
 WebView web;final ExecutorService worker=Executors.newSingleThreadExecutor();boolean destroyed=false;
 public void onCreate(Bundle state){boolean dark=(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;setTheme(dark?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);super.onCreate(state);
  web=new WebView(this);web.setBackgroundColor(Color.parseColor(dark?"#121212":"#f2f3f5"));setContentView(web);web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(0,insets.getSystemWindowInsetTop(),0,insets.getSystemWindowInsetBottom());return insets;});web.requestApplyInsets();
  if(Build.VERSION.SDK_INT>=30){WindowInsetsController controller=getWindow().getInsetsController();if(controller!=null)controller.setSystemBarsAppearance(dark?0:WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS);}
  WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setAllowFileAccessFromFileURLs(false);settings.setAllowUniversalAccessFromFileURLs(false);settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);
  web.addJavascriptInterface(new Bridge(),"FileManagerNative");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return true;}public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(!url.startsWith("file:///android_asset/"))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));String name=url.substring("file:///android_asset/".length());if(!name.matches("dashboard\\.(html|css|js)|watch-editor\\.js"))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{return new WebResourceResponse(name.endsWith("css")?"text/css":name.endsWith("js")?"application/javascript":"text/html","UTF-8",getAssets().open(name));}catch(IOException ex){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}});web.loadUrl("file:///android_asset/dashboard.html");
 }
 final class Bridge {
  @JavascriptInterface public String permissions(){try{boolean notification=(Build.VERSION.SDK_INT<33||checkSelfPermission("android.permission.POST_NOTIFICATIONS")==PackageManager.PERMISSION_GRANTED)&&getSystemService(NotificationManager.class).areNotificationsEnabled();return new JSONObject().put("notifications",notification).put("overlay",Settings.canDrawOverlays(MainActivity.this)).put("battery",getSystemService(PowerManager.class).isIgnoringBatteryOptimizations(getPackageName())).put("reminders",getSharedPreferences("helper",0).getBoolean("reminders",true)).put("connected",getSharedPreferences("helper",0).getBoolean("connected",false)).toString();}catch(Exception ex){return "{}";}}
  @JavascriptInterface public void call(String action,String body,String id){if(id==null||!id.matches("[a-zA-Z0-9_]{1,64}")||body==null||body.length()>262144)return;worker.execute(()->{JSONObject response=new JSONObject();try{if(action.equals("watch-save")){String expected="v"+getPackageManager().getPackageInfo(getPackageName(),0).versionName;JSONObject info=Root.call("watch-status",new JSONObject());if(!expected.equals(info.optString("version")))throw new IOException("页面与模块版本不同，请完成模块更新后再保存规则");}JSONObject data=Root.call(action,new JSONObject(body));response.put("ok",true).put("data",data==null?JSONObject.NULL:data);if(action.equals("watch-status"))getSharedPreferences("helper",0).edit().putBoolean("connected",true).apply();}catch(Exception ex){try{response.put("ok",false).put("error",ex.getMessage()==null?"操作失败":ex.getMessage());}catch(Exception ignored){}}String encoded=response.toString();runOnUiThread(()->{if(!destroyed)web.evaluateJavascript("window.fmReply("+JSONObject.quote(id)+","+encoded+")",null);});});}
  @JavascriptInterface public void setting(String name){runOnUiThread(()->{try{switch(name){case "notifications":if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);else startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));break;case "overlay":startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));break;case "battery":startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));break;case "start":getSharedPreferences("helper",0).edit().putBoolean("reminders",true).apply();startForegroundService(new Intent(MainActivity.this,MonitorService.class));break;case "pause":getSharedPreferences("helper",0).edit().putBoolean("reminders",false).apply();stopService(new Intent(MainActivity.this,MonitorService.class));break;default:return;}web.evaluateJavascript("window.refreshPermissions&&window.refreshPermissions()",null);}catch(Exception ex){web.evaluateJavascript("window.showMessage("+JSONObject.quote(ex.getMessage())+")",null);}});}
 }
 public void onResume(){super.onResume();if(web!=null)web.evaluateJavascript("window.refreshPermissions&&window.refreshPermissions()",null);}
 public void onDestroy(){destroyed=true;worker.shutdownNow();if(web!=null){web.removeJavascriptInterface("FileManagerNative");web.destroy();}super.onDestroy();}
}
